namespace ghidra.feature.vt.gui.filters;







using docking;
using docking.widgets.checkbox;
using docking.widgets.list;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.editors;
using ghidra.feature.vt.gui.plugin;
using ghidra.framework.plugintool;

public class TagFilterEditorDialog : DialogComponentProvider, TagFilterChooser {

	private Map<string, VTMatchTag> allTags;
	private Map<string, VTMatchTag> excludedTags;
	private TagListModel listModel;
	private VTController controller;

	public TagFilterEditorDialog(VTController controller) : base("Tag Chooser", true, false, true, false)
    {
		this.controller = controller;

		setPreferredSize(300, 400); // setup a decent size
		addOKButton();
	}

	private JPanel createWorkPanel() {
		JPanel mainPanel = new JPanel(new BorderLayout());

		JScrollPane scrollPane = new JScrollPane();
		scrollPane.getAccessibleContext().setAccessibleName("Tag List");
		listModel = new TagListModel(allTags, excludedTags);
		JList list = new JList(listModel);
		list.getAccessibleContext().setAccessibleName("Tag");
		list.setBackground(scrollPane.getBackground());
		list.setCellRenderer(new TagRenderer());
		list.getSelectionModel().setSelectionMode(ListSelectionModel.SINGLE_SELECTION);

		list.addMouseListener(new _Anon_MouseAdapter_1());

		scrollPane.setViewportView(list);
		mainPanel.add(scrollPane, BorderLayout.CENTER);

		JButton editButton = new JButton("Manage Tags");
		editButton.getAccessibleContext().setAccessibleName("Edit");
		editButton.addActionListener(new _Anon_ActionListener_2());

		JPanel editPanel = new JPanel();
		editPanel.getAccessibleContext().setAccessibleName("Edit");
		editPanel.add(editButton);

		mainPanel.add(editPanel, BorderLayout.SOUTH);
		mainPanel.getAccessibleContext().setAccessibleName("Tag Filter Editor");
		return mainPanel;
	}

	/* @Override */
	public Map<string, VTMatchTag> getExcludedTags(Map<string, VTMatchTag> allTagsMap,
			Map<string, VTMatchTag> currentExcludedTagsMap) {
		this.allTags = allTagsMap;
		this.excludedTags = currentExcludedTagsMap;

		rebuild();

		PluginTool tool = controller.getTool();
		tool.showDialog(this);

		int size = listModel.getSize();
		Map<string, VTMatchTag> newExcludedTags = new();
		for (int i = 0; i < size; i++) {
			TagInfo info = (TagInfo) listModel.get(i);
			if (!info.isIncluded()) {
				VTMatchTag tag = info.getTag();
				newExcludedTags.put(tag.getName(), tag);
			}
		}
		return newExcludedTags;
	}

	private Map<string, VTMatchTag> getAllTags() {
		VTSession session = controller.getSession();
		if (session == null) {
			return Collections.emptyMap();
		}
		TreeMap<string, VTMatchTag> map = new();

		Set<VTMatchTag> matchTags = session.getMatchTags();
		foreach (VTMatchTag tag in matchTags) {
			map.put(tag.getName(), tag);
		}

		map.put(VTMatchTag.UNTAGGED.getName(), VTMatchTag.UNTAGGED);

		return map;
	}

	private void rebuild() {
		removeWorkPanel();
		addWorkPanel(createWorkPanel());
	}

	/* @Override */
	protected void okCallback() {
		close();
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private class TagListModel : DefaultListModel<TagInfo> {
		TagListModel(Map<string, VTMatchTag> allTags, Map<string, VTMatchTag> excludedTags) {
			foreach (Map.Entry<string, VTMatchTag> entry in allTags.entrySet()) {
				bool isExcluded = excludedTags.containsKey(entry.getKey());
				addElement(new TagInfo(entry.getValue(), !isExcluded));
			}
		}
	}

	private class TagInfo {
		private bool isIncluded;
		private VTMatchTag tag;

		TagInfo(VTMatchTag tag, bool isIncluded) {
			this.tag = tag;
			this.isIncluded = isIncluded;
		}

		VTMatchTag getTag() {
			return tag;
		}

		bool isIncluded() {
			return isIncluded;
		}

		void setIncluded(bool isIncluded) {
			this.isIncluded = isIncluded;
		}

		string getDisplayText() {
			string name = tag.getName();
			if (tag == VTMatchTag.UNTAGGED) {
				name = tag.toString();
			}
			string status = isIncluded ? "included" : "excluded";
			return name + " (" + status + ")";
		}
	}

	private class TagRenderer : GListCellRenderer<TagInfo> {

		private JPanel panel;
		private GCheckBox checkBox = new GCheckBox();

		/* @Override */
		public Component getListCellRendererComponent(JList<TagInfo> list, TagInfo value,
				int index, bool isSelected, bool cellHasFocus) {
			JLabel renderer = (JLabel) base.getListCellRendererComponent(list, value, index,
				isSelected, cellHasFocus);

			checkBox.setSelected(value.isIncluded);

			renderer.setText(value.getDisplayText());

			return getPanel(renderer);
		}

		private JPanel getPanel(JLabel renderer) {
			if (panel == null) {
				JScrollPane scrollPane = new JScrollPane();
				panel = new JPanel();

				// let our color match that of the scroll pane our list is inside of
				panel.setBackground(scrollPane.getBackground());

				panel.setLayout(new BoxLayout(panel, BoxLayout.X_AXIS));
				panel.add(checkBox);
				panel.add(Box.createHorizontalStrut(5));
				panel.add(renderer);
			}
			return panel;
		}
	}

	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

			/* @Override */
			public void mouseClicked(MouseEvent e) {
				int index = list.locationToIndex(e.getPoint());
				Rectangle cellBounds = list.getCellBounds(index, index);
				if (cellBounds == null) {
					return;
				}
				if (cellBounds.contains(e.getPoint())) {
					TagInfo info = (TagInfo) listModel.get(index);
					info.setIncluded(!info.isIncluded());
					list.repaint();
				}
			}
		
	}


	internal class _Anon_ActionListener_2 : ActionListener
	{

			/* @Override */
			public void actionPerformed(ActionEvent e) {

				// show the editor
				TagEditorDialog dialog = new TagEditorDialog(controller.getSession());
				PluginTool tool = controller.getTool();
				tool.showDialog(dialog);

				allTags = getAllTags();

				// update our list of tags
				rebuild();
			}
		
	}

}
